PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE app_settings (   key TEXT PRIMARY KEY,   value_json TEXT NOT NULL,   updated_at TEXT NOT NULL , tenant_id TEXT NOT NULL DEFAULT 'default');
CREATE TABLE saas_tenants (   id TEXT PRIMARY KEY,   slug TEXT NOT NULL UNIQUE,   name TEXT NOT NULL,   legal_name TEXT,   contact_name TEXT,   contact_email TEXT,   contact_phone TEXT,   status TEXT NOT NULL DEFAULT 'trial',   plan TEXT NOT NULL DEFAULT 'starter',   domain TEXT,   subdomain TEXT,   brand_json TEXT NOT NULL DEFAULT '{}',   settings_json TEXT NOT NULL DEFAULT '{}',   notes TEXT,   created_at_utc TEXT NOT NULL,   updated_at_utc TEXT NOT NULL );
CREATE TABLE saas_users (   id TEXT PRIMARY KEY,   tenant_id TEXT,   name TEXT NOT NULL,   email TEXT,   phone TEXT,   role TEXT NOT NULL,   status TEXT NOT NULL DEFAULT 'active',   password_hint TEXT,   created_at_utc TEXT NOT NULL,   updated_at_utc TEXT NOT NULL );
CREATE TABLE saas_subscriptions (   id TEXT PRIMARY KEY,   tenant_id TEXT NOT NULL,   plan TEXT NOT NULL,   status TEXT NOT NULL DEFAULT 'trial',   monthly_price_cents INTEGER NOT NULL DEFAULT 0,   currency TEXT NOT NULL DEFAULT 'MXN',   trial_ends_at TEXT,   current_period_starts_at TEXT,   current_period_ends_at TEXT,   last_payment_at TEXT,   next_payment_due_at TEXT,   notes TEXT,   created_at_utc TEXT NOT NULL,   updated_at_utc TEXT NOT NULL , provider TEXT NOT NULL DEFAULT 'manual', mp_preapproval_id TEXT, mp_payer_email TEXT, checkout_url TEXT, provider_status TEXT, provider_synced_at TEXT);
CREATE TABLE audit_log (   id INTEGER PRIMARY KEY AUTOINCREMENT,   tenant_id TEXT,   actor_role TEXT NOT NULL,   actor_name TEXT,   action TEXT NOT NULL,   entity_type TEXT,   entity_id TEXT,   metadata_json TEXT NOT NULL DEFAULT '{}',   created_at_utc TEXT NOT NULL );
CREATE TABLE stock_units (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      code TEXT NOT NULL UNIQUE,
      name TEXT NOT NULL,
      kind TEXT NOT NULL DEFAULT 'general',
      sort_order INTEGER NOT NULL DEFAULT 0
    , tenant_id TEXT NOT NULL DEFAULT 'default');
CREATE TABLE stock_branches (
      id TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      active INTEGER NOT NULL DEFAULT 1,
      is_default INTEGER NOT NULL DEFAULT 0,
      created_at_utc TEXT NOT NULL,
      updated_at_utc TEXT NOT NULL
    , tenant_id TEXT NOT NULL DEFAULT 'default');
CREATE TABLE inventory_branch_stock (
      item_id INTEGER NOT NULL,
      branch_id TEXT NOT NULL,
      current_stock REAL NOT NULL DEFAULT 0,
      updated_at_utc TEXT NOT NULL, tenant_id TEXT NOT NULL DEFAULT 'default',
      PRIMARY KEY (item_id, branch_id),
      FOREIGN KEY (item_id) REFERENCES "items"(id)
    );
CREATE TABLE stock_movements (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      item_id INTEGER NOT NULL,
      movement_type TEXT NOT NULL,
      quantity REAL NOT NULL,
      stock_before REAL NOT NULL,
      stock_after REAL NOT NULL,
      reason TEXT,
      source_type TEXT,
      source_id TEXT,
      reported_by TEXT,
      reported_role TEXT,
      reported_shift TEXT,
      approved_by TEXT,
      branch_id TEXT NOT NULL DEFAULT 'dominio',
      branch_name TEXT,
      created_at_utc TEXT NOT NULL,
      created_at_monterrey TEXT NOT NULL, tenant_id TEXT NOT NULL DEFAULT 'default',
      FOREIGN KEY (item_id) REFERENCES "items"(id)
    );
CREATE TABLE waste_requests (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      item_id INTEGER NOT NULL,
      quantity REAL NOT NULL,
      reason TEXT NOT NULL,
      status TEXT NOT NULL DEFAULT 'pending',
      reported_by TEXT NOT NULL,
      reported_role TEXT NOT NULL,
      reported_shift TEXT NOT NULL,
      approved_by TEXT,
      branch_id TEXT NOT NULL DEFAULT 'dominio',
      branch_name TEXT,
      created_at_utc TEXT NOT NULL,
      created_at_monterrey TEXT NOT NULL,
      updated_at_utc TEXT NOT NULL,
      updated_at_monterrey TEXT NOT NULL, tenant_id TEXT NOT NULL DEFAULT 'default',
      FOREIGN KEY (item_id) REFERENCES "items"(id)
    );
CREATE TABLE inventory_count_requests (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      item_id INTEGER NOT NULL,
      requested_stock REAL NOT NULL,
      current_stock_snapshot REAL NOT NULL DEFAULT 0,
      difference REAL NOT NULL DEFAULT 0,
      reason TEXT,
      status TEXT NOT NULL DEFAULT 'pending',
      reported_by TEXT NOT NULL,
      reported_role TEXT NOT NULL,
      reported_shift TEXT NOT NULL,
      approved_by TEXT,
      branch_id TEXT NOT NULL DEFAULT 'dominio',
      branch_name TEXT,
      created_at_utc TEXT NOT NULL,
      created_at_monterrey TEXT NOT NULL,
      updated_at_utc TEXT NOT NULL,
      updated_at_monterrey TEXT NOT NULL, tenant_id TEXT NOT NULL DEFAULT 'default',
      FOREIGN KEY (item_id) REFERENCES "items"(id)
    );
CREATE TABLE IF NOT EXISTS "recipe_lines" (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      recipe_id INTEGER NOT NULL,
      item_id INTEGER NOT NULL,
      quantity REAL NOT NULL DEFAULT 0,
      line_role TEXT NOT NULL DEFAULT 'ingrediente',
      client_visible INTEGER NOT NULL DEFAULT 0,
      client_removable INTEGER NOT NULL DEFAULT 0,
      client_changeable INTEGER NOT NULL DEFAULT 0,
      is_default INTEGER NOT NULL DEFAULT 0,
      is_optional INTEGER NOT NULL DEFAULT 0,
      is_extra_billable INTEGER NOT NULL DEFAULT 0,
      extra_price REAL NOT NULL DEFAULT 0,
      sort_order INTEGER NOT NULL DEFAULT 0, tenant_id TEXT NOT NULL DEFAULT 'default', notes TEXT, waste_percent REAL NOT NULL DEFAULT 0,
      FOREIGN KEY (recipe_id) REFERENCES "recipes"(id),
      FOREIGN KEY (item_id) REFERENCES "items"(id)
    );
CREATE TABLE stock_option_family_items (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      family_id INTEGER NOT NULL,
      item_id INTEGER NOT NULL,
      option_name TEXT NOT NULL,
      quantity REAL NOT NULL DEFAULT 0,
      extra_price REAL NOT NULL DEFAULT 0,
      is_default INTEGER NOT NULL DEFAULT 0,
      is_active INTEGER NOT NULL DEFAULT 1,
      sort_order INTEGER NOT NULL DEFAULT 0,
      created_at_utc TEXT NOT NULL,
      updated_at_utc TEXT NOT NULL, tenant_id TEXT NOT NULL DEFAULT 'default',
      UNIQUE(family_id, option_name),
      FOREIGN KEY (family_id) REFERENCES stock_option_families(id),
      FOREIGN KEY (item_id) REFERENCES "items"(id)
    );
CREATE TABLE stock_option_family_item_components (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      option_item_id INTEGER NOT NULL,
      item_id INTEGER NOT NULL,
      quantity REAL NOT NULL DEFAULT 0,
      sort_order INTEGER NOT NULL DEFAULT 0,
      created_at_utc TEXT NOT NULL,
      updated_at_utc TEXT NOT NULL, tenant_id TEXT NOT NULL DEFAULT 'default',
      UNIQUE(option_item_id, item_id),
      FOREIGN KEY (option_item_id) REFERENCES stock_option_family_items(id),
      FOREIGN KEY (item_id) REFERENCES "items"(id)
    );
CREATE TABLE stock_product_option_groups (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      product_id TEXT NOT NULL,
      family_id INTEGER NOT NULL,
      label TEXT,
      min_select INTEGER NOT NULL DEFAULT 0,
      max_included INTEGER NOT NULL DEFAULT 0,
      max_total INTEGER NOT NULL DEFAULT 1,
      default_option_name TEXT,
      extra_price REAL NOT NULL DEFAULT 0,
      is_required INTEGER NOT NULL DEFAULT 0,
      is_active INTEGER NOT NULL DEFAULT 1,
      sort_order INTEGER NOT NULL DEFAULT 0,
      created_at_utc TEXT NOT NULL,
      updated_at_utc TEXT NOT NULL, tenant_id TEXT NOT NULL DEFAULT 'default',
      UNIQUE(product_id, family_id),
      FOREIGN KEY (family_id) REFERENCES stock_option_families(id)
    );
CREATE TABLE order_items (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      order_id INTEGER NOT NULL,
      product_id TEXT,
      product_name TEXT NOT NULL,
      category TEXT NOT NULL,
      quantity INTEGER NOT NULL DEFAULT 1,
      unit_price INTEGER NOT NULL DEFAULT 0,
      line_total INTEGER NOT NULL DEFAULT 0,
      options_json TEXT,
      item_notes TEXT,
      created_at_utc TEXT NOT NULL,
      created_at_monterrey TEXT NOT NULL, tenant_id TEXT NOT NULL DEFAULT 'default',
      FOREIGN KEY (order_id) REFERENCES orders(id)
    );
CREATE TABLE order_events (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      order_id INTEGER NOT NULL,
      event_type TEXT NOT NULL,
      event_note TEXT,
      created_at_utc TEXT NOT NULL,
      created_at_monterrey TEXT NOT NULL, tenant_id TEXT NOT NULL DEFAULT 'default',
      FOREIGN KEY (order_id) REFERENCES orders(id)
    );
CREATE TABLE saas_tenant_domains (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    hostname TEXT NOT NULL UNIQUE,
    kind TEXT NOT NULL DEFAULT 'custom',
    status TEXT NOT NULL DEFAULT 'active',
    cf_hostname_id TEXT,
    ssl_status TEXT,
    created_at_utc TEXT NOT NULL,
    updated_at_utc TEXT NOT NULL
  );
CREATE TABLE users (
  id TEXT PRIMARY KEY,
  tenant_id TEXT,
  email TEXT NOT NULL,
  name TEXT NOT NULL,
  password_hash TEXT NOT NULL,
  role TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'active',
  last_login_at_utc TEXT,
  created_at_utc TEXT NOT NULL,
  updated_at_utc TEXT NOT NULL,
  UNIQUE (tenant_id, email)
);
CREATE TABLE user_sessions (
  id TEXT PRIMARY KEY,
  tenant_id TEXT,
  user_id TEXT NOT NULL,
  role TEXT NOT NULL,
  expires_at_utc TEXT NOT NULL,
  created_at_utc TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS "orders" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tenant_id TEXT NOT NULL DEFAULT 'default',
  order_number TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending',
  branch_id TEXT NOT NULL DEFAULT 'dominio',
  branch_name TEXT NOT NULL DEFAULT 'Dominio',
  customer_name TEXT NOT NULL,
  customer_phone TEXT NOT NULL,
  customer_address TEXT NOT NULL,
  customer_notes TEXT,
  subtotal INTEGER NOT NULL DEFAULT 0,
  delivery_fee INTEGER NOT NULL DEFAULT 0,
  total INTEGER NOT NULL DEFAULT 0,
  whatsapp_message TEXT,
  created_at_utc TEXT NOT NULL,
  created_at_monterrey TEXT NOT NULL,
  timezone TEXT NOT NULL DEFAULT 'America/Monterrey',
  updated_at_utc TEXT NOT NULL,
  updated_at_monterrey TEXT NOT NULL,
  stock_deducted INTEGER NOT NULL DEFAULT 0,
  stock_deducted_at_utc TEXT,
  stock_deducted_at_monterrey TEXT,
  stock_deduction_error TEXT,
  order_source TEXT NOT NULL DEFAULT 'online',
  cashier_name TEXT,
  cashier_shift TEXT,
  payment_method TEXT,
  payment_status TEXT
, payment_provider TEXT, payment_preference_id TEXT, provider_payment_id TEXT, provider_merchant_order_id TEXT, payment_amount INTEGER, marketplace_fee INTEGER DEFAULT 0, paid_at TEXT, exclude_from_reports INTEGER NOT NULL DEFAULT 0, archived_at_utc TEXT, archived_reason TEXT, deleted_at_utc TEXT, custom_fields_json TEXT, customer_neighborhood TEXT, price_override_count INTEGER NOT NULL DEFAULT 0, price_override_by_role TEXT, price_override_by_name TEXT);
CREATE TABLE IF NOT EXISTS "stock_purchase_categories" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tenant_id TEXT NOT NULL DEFAULT 'default',
  name TEXT NOT NULL,
  sort_order INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS "stock_suppliers" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tenant_id TEXT NOT NULL DEFAULT 'default',
  name TEXT NOT NULL,
  notes TEXT
);
CREATE TABLE IF NOT EXISTS "items" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tenant_id TEXT NOT NULL DEFAULT 'default',
  name TEXT NOT NULL,
  brand TEXT,
  item_type TEXT NOT NULL DEFAULT 'Ingrediente comprado',
  unit_id INTEGER NOT NULL,
  current_stock REAL NOT NULL DEFAULT 0,
  min_stock REAL NOT NULL DEFAULT 0,
  max_stock REAL NOT NULL DEFAULT 0,
  accuracy_target REAL NOT NULL DEFAULT 85,
  primary_supplier_id INTEGER,
  alt_supplier_id INTEGER,
  purchase_category_id INTEGER,
  purchase_unit_label TEXT,
  purchase_unit_quantity REAL NOT NULL DEFAULT 0,
  purchase_price REAL NOT NULL DEFAULT 0,
  expiry_date TEXT,
  is_active INTEGER NOT NULL DEFAULT 1,
  client_visible INTEGER NOT NULL DEFAULT 0,
  client_removable INTEGER NOT NULL DEFAULT 0,
  client_changeable INTEGER NOT NULL DEFAULT 0,
  deducts_inventory INTEGER NOT NULL DEFAULT 1,
  is_packaging INTEGER NOT NULL DEFAULT 0,
  is_internal_dressing INTEGER NOT NULL DEFAULT 0,
  is_side_dressing INTEGER NOT NULL DEFAULT 0,
  is_sellable_extra INTEGER NOT NULL DEFAULT 0,
  created_at_utc TEXT NOT NULL,
  updated_at_utc TEXT NOT NULL, type TEXT, family_id INTEGER, sku TEXT, is_sellable INTEGER NOT NULL DEFAULT 0, is_purchasable INTEGER NOT NULL DEFAULT 1, is_producible INTEGER NOT NULL DEFAULT 0, is_modifier INTEGER NOT NULL DEFAULT 0,
  FOREIGN KEY (unit_id) REFERENCES stock_units(id)
);
CREATE TABLE IF NOT EXISTS "recipes" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tenant_id TEXT NOT NULL DEFAULT 'default',
  recipe_key TEXT NOT NULL,
  recipe_type TEXT NOT NULL DEFAULT 'product',
  name TEXT NOT NULL,
  output_item_id INTEGER,
  output_quantity REAL NOT NULL DEFAULT 0,
  notes TEXT,
  is_active INTEGER NOT NULL DEFAULT 1,
  created_at_utc TEXT NOT NULL,
  updated_at_utc TEXT NOT NULL, item_id INTEGER, version INTEGER NOT NULL DEFAULT 1, status TEXT NOT NULL DEFAULT 'active', waste_percent REAL NOT NULL DEFAULT 0,
  FOREIGN KEY (output_item_id) REFERENCES "items"(id)
);
CREATE TABLE IF NOT EXISTS "stock_option_families" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tenant_id TEXT NOT NULL DEFAULT 'default',
  family_key TEXT NOT NULL,
  name TEXT NOT NULL,
  description TEXT,
  sort_order INTEGER NOT NULL DEFAULT 0,
  is_active INTEGER NOT NULL DEFAULT 1,
  created_at_utc TEXT NOT NULL,
  updated_at_utc TEXT NOT NULL
);
CREATE TABLE menu_categories (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tenant_id TEXT NOT NULL,
  category_key TEXT NOT NULL,
  label TEXT NOT NULL,
  emoji TEXT NOT NULL DEFAULT '',
  description TEXT NOT NULL DEFAULT '',
  sort_order INTEGER NOT NULL DEFAULT 0,
  is_visible INTEGER NOT NULL DEFAULT 1,
  is_active INTEGER NOT NULL DEFAULT 1,
  created_at_utc TEXT NOT NULL,
  updated_at_utc TEXT NOT NULL,
  UNIQUE(tenant_id, category_key)
);
CREATE TABLE menu_products (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tenant_id TEXT NOT NULL,
  product_key TEXT NOT NULL,
  category_key TEXT NOT NULL,
  recipe_id INTEGER,
  name TEXT NOT NULL,
  product_type TEXT NOT NULL DEFAULT 'custom',
  price REAL NOT NULL DEFAULT 0,
  badge TEXT NOT NULL DEFAULT '',
  description TEXT NOT NULL DEFAULT '',
  ingredients TEXT NOT NULL DEFAULT '',
  image TEXT NOT NULL DEFAULT '',
  is_published INTEGER NOT NULL DEFAULT 1,
  is_active INTEGER NOT NULL DEFAULT 1,
  metadata_json TEXT NOT NULL DEFAULT '{}',
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_at_utc TEXT NOT NULL,
  updated_at_utc TEXT NOT NULL, item_id INTEGER,
  UNIQUE(tenant_id, product_key),
  FOREIGN KEY (tenant_id, category_key) REFERENCES menu_categories(tenant_id, category_key),
  FOREIGN KEY (recipe_id) REFERENCES "recipes"(id)
);
CREATE TABLE menu_product_recipe_links (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tenant_id TEXT NOT NULL,
  product_key TEXT NOT NULL,
  recipe_id INTEGER NOT NULL,
  link_type TEXT NOT NULL DEFAULT 'primary',
  is_active INTEGER NOT NULL DEFAULT 1,
  created_at_utc TEXT NOT NULL,
  updated_at_utc TEXT NOT NULL,
  UNIQUE(tenant_id, product_key, recipe_id, link_type),
  FOREIGN KEY (tenant_id, product_key) REFERENCES menu_products(tenant_id, product_key),
  FOREIGN KEY (recipe_id) REFERENCES "recipes"(id)
);
CREATE TABLE tenant_payment_connections (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  provider TEXT NOT NULL DEFAULT 'mercado_pago',

  provider_user_id TEXT,
  public_key TEXT,

  access_token_encrypted TEXT,
  refresh_token_encrypted TEXT,
  token_expires_at TEXT,
  scopes TEXT,

  connection_status TEXT NOT NULL DEFAULT 'disconnected',
  connected_at TEXT,
  disconnected_at TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY (tenant_id) REFERENCES saas_tenants(id),
  UNIQUE (tenant_id, provider)
);
CREATE TABLE oauth_sessions (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  provider TEXT NOT NULL,
  state_hash TEXT NOT NULL UNIQUE,
  code_verifier_encrypted TEXT,
  expires_at TEXT NOT NULL,
  used_at TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE payment_webhook_events (
  id TEXT PRIMARY KEY,
  provider TEXT NOT NULL,
  provider_event_id TEXT NOT NULL,
  tenant_id TEXT,
  event_type TEXT,
  resource_id TEXT,
  processing_status TEXT NOT NULL,
  received_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  processed_at TEXT,
  error_message TEXT,

  UNIQUE(provider, provider_event_id)
);
CREATE TABLE tenant_whatsapp_connections (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,

  waba_id TEXT,
  phone_number_id TEXT,
  display_phone_number TEXT,
  business_name TEXT,

  access_token_encrypted TEXT,
  token_expires_at TEXT,

  connection_status TEXT NOT NULL DEFAULT 'disconnected',
  connected_at TEXT,
  disconnected_at TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY (tenant_id) REFERENCES saas_tenants(id),
  UNIQUE (tenant_id)
);
CREATE TABLE whatsapp_conversations (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  customer_phone TEXT NOT NULL,
  state TEXT NOT NULL DEFAULT 'idle',
  cart_json TEXT NOT NULL DEFAULT '{}',
  order_id INTEGER,
  last_message_at TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (tenant_id, customer_phone)
);
CREATE TABLE whatsapp_messages (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  customer_phone TEXT NOT NULL,
  direction TEXT NOT NULL, -- inbound | outbound
  message_type TEXT,
  wa_message_id TEXT,
  content_json TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE whatsapp_webhook_events (
  id TEXT PRIMARY KEY,
  provider_event_id TEXT NOT NULL UNIQUE,
  tenant_id TEXT,
  event_type TEXT,
  processing_status TEXT NOT NULL,
  received_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  processed_at TEXT,
  error_message TEXT
);
CREATE TABLE tenant_meta_page_connections (
      id TEXT PRIMARY KEY,
      tenant_id TEXT NOT NULL,
      page_id TEXT,
      page_name TEXT,
      page_access_token_encrypted TEXT,
      instagram_business_account_id TEXT,
      instagram_username TEXT,
      connection_status TEXT NOT NULL DEFAULT 'disconnected',
      connected_at TEXT,
      disconnected_at TEXT,
      created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
      updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
      UNIQUE (tenant_id)
    );
CREATE TABLE tenant_instagram_login_connections (
      id TEXT PRIMARY KEY,
      tenant_id TEXT NOT NULL,
      ig_user_id TEXT,
      ig_username TEXT,
      access_token_encrypted TEXT,
      token_expires_at TEXT,
      connection_status TEXT NOT NULL DEFAULT 'disconnected',
      connected_at TEXT,
      disconnected_at TEXT,
      created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
      updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
      UNIQUE (tenant_id)
    );
CREATE TABLE meta_channel_conversations (
      id TEXT PRIMARY KEY,
      tenant_id TEXT NOT NULL,
      channel TEXT NOT NULL,
      customer_id TEXT NOT NULL,
      state TEXT NOT NULL DEFAULT 'idle',
      cart_json TEXT NOT NULL DEFAULT '{}',
      order_id INTEGER,
      last_message_at TEXT,
      created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
      updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
      UNIQUE (tenant_id, channel, customer_id)
    );
CREATE TABLE meta_channel_messages (
      id TEXT PRIMARY KEY,
      tenant_id TEXT NOT NULL,
      channel TEXT NOT NULL,
      customer_id TEXT NOT NULL,
      direction TEXT NOT NULL,
      message_type TEXT,
      provider_message_id TEXT,
      content_json TEXT,
      created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE meta_channel_webhook_events (
      id TEXT PRIMARY KEY,
      provider_event_id TEXT NOT NULL UNIQUE,
      tenant_id TEXT,
      channel TEXT,
      event_type TEXT,
      processing_status TEXT NOT NULL,
      received_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
      processed_at TEXT,
      error_message TEXT
    );
CREATE TABLE crm_customers (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      tenant_id TEXT NOT NULL DEFAULT 'default',
      customer_key TEXT NOT NULL,
      name TEXT NOT NULL,
      phone TEXT,
      address TEXT,
      neighborhood TEXT,
      sector TEXT,
      tags_json TEXT NOT NULL DEFAULT '[]',
      notes TEXT,
      order_count INTEGER NOT NULL DEFAULT 0,
      total_spent INTEGER NOT NULL DEFAULT 0,
      last_order_id INTEGER,
      last_order_number TEXT,
      last_order_at_utc TEXT,
      created_at_utc TEXT NOT NULL,
      updated_at_utc TEXT NOT NULL
    );
CREATE TABLE branch_order_counters (
  tenant_id TEXT NOT NULL,
  branch_id TEXT NOT NULL,
  next_number INTEGER NOT NULL DEFAULT 1,
  PRIMARY KEY (tenant_id, branch_id)
);
CREATE TABLE families (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tenant_id TEXT NOT NULL DEFAULT 'default',
  name TEXT NOT NULL,
  description TEXT,
  sort_order INTEGER NOT NULL DEFAULT 0,
  is_active INTEGER NOT NULL DEFAULT 1
);
CREATE TABLE unit_conversions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tenant_id TEXT NOT NULL DEFAULT 'default',
  item_id INTEGER,
  from_unit TEXT NOT NULL,
  to_unit TEXT NOT NULL,
  factor REAL NOT NULL
);
CREATE TABLE support_tickets (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  title TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'open',
  priority TEXT NOT NULL DEFAULT 'normal',
  requested_by TEXT,
  message TEXT NOT NULL DEFAULT '',
  created_at_utc TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at_utc TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE login_attempts (
      attempt_key TEXT PRIMARY KEY,
      attempts INTEGER NOT NULL DEFAULT 0,
      window_start_utc TEXT NOT NULL
    );
CREATE TABLE receivables (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    order_id TEXT,
    order_number TEXT,
    customer_id INTEGER,
    customer_name TEXT NOT NULL,
    customer_phone TEXT,
    sale_type TEXT NOT NULL DEFAULT 'credit',
    status TEXT NOT NULL DEFAULT 'active',
    principal_amount INTEGER NOT NULL DEFAULT 0,
    down_payment_amount INTEGER NOT NULL DEFAULT 0,
    paid_amount INTEGER NOT NULL DEFAULT 0,
    balance_amount INTEGER NOT NULL DEFAULT 0,
    currency TEXT NOT NULL DEFAULT 'MXN',
    due_date TEXT,
    next_payment_date TEXT,
    reserved_until_date TEXT,
    delivered_at_utc TEXT,
    notes TEXT,
    created_by_user_id TEXT,
    created_by_name TEXT,
    paid_at_utc TEXT,
    cancelled_at_utc TEXT,
    cancelled_reason TEXT,
    created_at_utc TEXT NOT NULL,
    updated_at_utc TEXT NOT NULL
  );
CREATE TABLE receivable_payments (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    receivable_id TEXT NOT NULL,
    amount INTEGER NOT NULL,
    payment_method TEXT NOT NULL,
    branch_id TEXT,
    branch_name TEXT,
    paid_at_utc TEXT NOT NULL,
    received_by_user_id TEXT,
    received_by_name TEXT,
    notes TEXT,
    status TEXT NOT NULL DEFAULT 'posted',
    voided_at_utc TEXT,
    voided_by_user_id TEXT,
    voided_by_name TEXT,
    void_reason TEXT,
    created_at_utc TEXT NOT NULL,
    updated_at_utc TEXT NOT NULL
  );
DELETE FROM sqlite_sequence;
CREATE INDEX idx_stock_recipe_lines_recipe ON "recipe_lines"(recipe_id);
CREATE INDEX idx_stock_option_family_items_family ON stock_option_family_items(family_id);
CREATE INDEX idx_stock_option_components_option ON stock_option_family_item_components(option_item_id);
CREATE INDEX idx_stock_product_option_groups_product ON stock_product_option_groups(product_id);
CREATE INDEX idx_stock_movements_item ON stock_movements(item_id, created_at_utc);
CREATE INDEX idx_stock_movements_branch ON stock_movements(branch_id, created_at_utc);
CREATE INDEX idx_inventory_branch_stock_branch ON inventory_branch_stock(branch_id);
CREATE INDEX idx_waste_requests_status ON waste_requests(status, created_at_utc);
CREATE INDEX idx_inventory_count_requests_status ON inventory_count_requests(status, created_at_utc);
CREATE INDEX idx_order_items_order_id ON order_items(order_id);
CREATE INDEX idx_app_settings_tenant_key ON app_settings(tenant_id, key);
CREATE INDEX idx_order_items_tenant_order ON order_items(tenant_id, order_id);
CREATE INDEX idx_order_events_tenant_order ON order_events(tenant_id, order_id);
CREATE INDEX idx_inventory_branch_stock_tenant_branch ON inventory_branch_stock(tenant_id, branch_id);
CREATE INDEX idx_stock_movements_tenant_branch ON stock_movements(tenant_id, branch_id, created_at_utc);
CREATE INDEX idx_users_tenant_role ON users(tenant_id, role, status);
CREATE INDEX idx_sessions_user ON user_sessions(user_id, expires_at_utc);
CREATE UNIQUE INDEX ux_orders_tenant_order_number ON orders(tenant_id, order_number);
